d="          {activeTab === 'overview' && latestIntake && (\n            <>\n              <Card className=\"border-l-4 border-l-primary-500\">\n                <div className=\"p-4 border-b flex items-center justify-between\"><div className=\"flex items-center gap-2\"><ClipboardList className=\"w-5 h-5 text-primary-600\" /><h2 className=\"font-semibold\">Patient-Reported Intake</h2></div><span className=\"text-xs text-neutral-500\">{new Date(latestIntake.created_at).toLocaleDateString()}</span></div>\n                <div className=\"p-4\">\n                  <div className=\"grid md:grid-cols-2 gap-4\">\n                    <div><p className=\"text-xs text-neutral-500 uppercase\">Chief Complaint</p><p className=\"font-medium\">{latestIntake.chief_complaint}</p></div>\n                    <div><p className=\"text-xs text-neutral-500 uppercase\">Location</p><p className=\"font-medium\">{latestIntake.location || '-'}</p></div>\n                    <div><p className=\"text-xs text-neutral-500 uppercase\">Duration</p><p className=\"font-medium\">{latestIntake.duration || '-'}</p></div>\n                    <div><p className=\"text-xs text-neutral-500 uppercase\">Pain Level</p><p className=\"font-medium\">{latestIntake.pain_level ? latestIntake.pain_level + '/10' : '-'}</p></div>\n                  </div>\n                  <div className=\"mt-4\"><p className=\"text-xs text-neutral-500 uppercase mb-2\">Symptoms</p><div className=\"flex flex-wrap gap-2\"><Badge variant={latestIntake.swelling ? 'warning' : 'secondary'}>Swelling</Badge><Badge variant={latestIntake.bleeding ? 'warning' : 'secondary'}>Bleeding</Badge><Badge variant={latestIntake.sensitivity ? 'warning' : 'secondary'}>Sensitivity</Badge><Badge variant={latestIntake.fever ? 'warning' : 'secondary'}>Fever</Badge></div></div>\n                </div>\n              </Card>\n              <Card className=\"bg-gradient-to-br from-primary-50 to-dental-50\">\n                <div className=\"p-4 border-b flex items-center justify-between\"><div className=\"flex items-center gap-2\"><FileText className=\"w-5 h-5 text-primary-600\" /><h2 className=\"font-semibold\">AI Summary</h2></div><Button variant=\"ghost\" size=\"sm\" onClick={generateAiSummary} disabled={generating}>{generating ? <span className=\"animate-spin\">Refresh</span> : 'Generate'}</Button></div>\n                <div className=\"p-4\">{aiSummary ? (<div className=\"bg-white/80 rounded-lg p-4\"><p className=\"text-sm leading-relaxed\">{aiSummary}</p><p className=\"text-xs text-neutral-500 mt-3 italic\">AI-generated summary. Not a diagnosis.</p></div>) : (<div className=\"text-center py-4\"><Button onClick={generateAiSummary} disabled={generating}>{generating ? 'Generating...' : 'Generate Summary'}</Button></div>)}</div>\n              </Card>\n            </>\n          )}\n          {activeTab === 'appointments' && (\n            <Card>\n              <div className=\"p-4 border-b flex items-center justify-between\"><h2 className=\"font-semibold\">Appointment History</h2><Button variant=\"outline\" size=\"sm\">New</Button></div>\n              <div className=\"divide-y\">{appointments.length === 0 ? <div className=\"p-8 text-center text-neutral-500\">No appointments</div> : appointments.map(apt => (<div key={apt.id} className=\"p-4 hover:bg-neutral-50\"><div className=\"flex items-center justify-between\"><div><p className=\"font-medium\">{new Date(apt.date).toLocaleDateString()}</p><p className=\"text-sm text-neutral-500\">{apt.start} - {apt.end_time} with {apt.dentist_name}</p></div><Badge variant={apt.status === 'completed' ? 'success' : 'primary'}>{apt.status}</Badge></div>{apt.notes && <p className=\"text-sm text-neutral-600 mt-2\">{apt.notes}</p>}</div>))}</div>\n            </Card>\n          )}\n          {activeTab === 'intake' && (\n            <Card><div className=\"p-4 border-b\"><h2 className=\"font-semibold\">Patient Intake Forms</h2></div><div className=\"divide-y\">{intakes.map(intake => (<div key={intake.id} className=\"p-4\"><div className=\"flex items-center justify-between mb-3\"><span className=\"text-sm text-neutral-500\">{new Date(intake.created_at).toLocaleDateString()}</span><Badge variant=\"primary\">Complete</Badge></div><div className=\"grid md:grid-cols-2 gap-2 text-sm\"><span className=\"text-neutral-500\">Complaint:</span><span className=\"font-medium\">{intake.chief_complaint}</span></div></div>))}</div></Card>\n          )}\n          {activeTab === 'notes' && (\n            <Card><div className=\"p-4 border-b flex items-center justify-between\"><h2 className=\"font-semibold\">Clinical Notes</h2><Button variant=\"outline\" size=\"sm\">Add Note</Button></div><div className=\"p-8 text-center text-neutral-500\"><MessageSquare className=\"w-12 h-12 mx-auto mb-3 opacity-50\" /><p>No clinical notes yet</p></div></Card>\n          )}\n        </div>\n      </div>\n    </div>\n  )\n}"
